    "pm_stats_label": "P150 MAX in numbers",
    "pm_spray_t": "Spraying",
    "pm_spray_p": "Intelligent centrifugal nozzles and two flexible impeller pumps meter the liquid precisely, and the downdraft of four rotors drives droplets deep into dense canopies. With the additional 4-Nozzle Upgrade Kit, flow rises to 46 L/min — recommended for orchards and vineyards.",
    "pm_f_flow": "Flow, two pumps",
    "pm_f_flow4": "With 4-nozzle kit",
    "pm_f_drop": "Droplet size",
    "pm_f_swath": "Spray width",
    "pm_spread_t": "Granule spreading",
    "pm_spread_p": "A vertical waving spreader with a direct-drive motor keeps the pattern even, even in wind. Large, medium and small screw feeders handle granules up to 10 mm — fertiliser, seed, feed — and the container fills from both sides.",
    "pm_f_rate": "Max spread rate*",
    "pm_f_spw": "Effective width",
    "pm_f_gran": "Max granule size",
    "pm_cargo_t": "Cargo transport",
    "pm_cargo_p": "Delivers farm inputs, harvest, seedling trays and saplings to hard-to-reach places. Secure load lock with automatic release, A/B routes, custom tracks for hilly terrain and live in-flight weighing.",
    "pm_f_slingspeed": "Max speed with cargo",
    "pm_map_t": "Field mapping",
    "pm_map_p": "Built in, no extra module: during autonomous flight it captures HD images, stitches them into a field map and hands it over right after landing. AI recognises obstacles, hilly fields get a 3D model preview, and prescription maps enable variable-rate application.",
    "pm_f_3d": "Model for hilly terrain",
    "pm_f_vra": "Variable rate by map",
    "pm_flight_t": "Flight and safety",
    "pm_flight_p": "A 4D imaging radar sees power poles, wires, centre pivots and other obstacles, day and night. Map-free 3D terrain following: the drone builds its 3D map in flight. A wide-angle FPV camera marks obstacles in AR, and the drone hovers automatically when something looks wrong.",
    "pm_f_radar": "Radar range",
    "pm_f_cpu": "Computing power vs SuperX 5 Pro",
    "pm_power_t": "Power and charging",
    "pm_power_p": "A 1050 Wh battery lasting up to 1500 cycles (warranty: 1 year or 1500 cycles). One CM13600S charger takes it from 30% to 95% in about 12 minutes, the parallel kit in 7. The mist cooling tank runs 6–8 hours on one tank, and the GC4000+ generator keeps you independent in the field. Single-battery mode: 50 L of liquid or 40 kg of granules.",
    "pm_f_wh": "Battery energy",
    "pm_f_cycles": "cycles",
    "pm_f_charge": "Charge 30→95%, parallel",
    "pm_f_kw": "Charger output",
    "pm_build_t": "Build and control",
    "pm_build_p": "IPX6K: wash the drone down with water. 63-inch propellers, folding arms and a modular build for transport. In the XAG One app: routes from the field shape, up to 10 fields per mission, two drones at once, and automatic return when liquid or power runs low. SRC 5 remote: 7-inch high-brightness screen, 8 hours of use. For centimetre accuracy, the XRTK 7 mobile station.",
    "pm_f_ip": "Protection rating",
    "pm_f_prop": "Propellers",
    "pm_f_fields": "fields per mission",
    "pm_f_link": "Video link (open field)",
    "pm_chapters_label": "Capabilities",
    "pm_notes": "* Tested with compound fertiliser; depends on granule size and density. Payload depends on configuration. Source: official XAG specifications.",
